# -*- coding: utf-8 -*-
# 5-arapca-15 görsel modülü

GORSELLER = {'b1': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect width="760" height="300" rx="14" fill="#f8fafc"/><text x="380" y="32" text-anchor="middle" font-size="16" font-weight="bold" fill="#1e293b">DİNLEME SÜRECİ: ÖNCESİ, SIRASI VE SONRASI</text><rect x="20" y="52" width="220" height="190" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/><text x="130" y="78" text-anchor="middle" font-size="14" font-weight="bold" fill="#1d4ed8">1. Dinlemeden Önce</text><text x="130" y="108" text-anchor="middle" font-size="12" fill="#1e3a8a">Görseldeki eşyaları say</text><text x="130" y="132" text-anchor="middle" font-size="12" fill="#1e3a8a">Bildiğin kelimeleri hatırla:</text><text x="130" y="154" text-anchor="middle" font-size="12" fill="#1e3a8a">sebbûratün · kitâbün · kalemün</text><text x="130" y="178" text-anchor="middle" font-size="12" fill="#1e3a8a">Metnin konusunu tahmin et</text><text x="130" y="212" text-anchor="middle" font-size="11" font-style="italic" fill="#1e40af">Hel hâzâ saffun? (Bu bir sınıf mı?)</text><line x1="244" y1="147" x2="258" y2="147" stroke="#64748b" stroke-width="2"/><polygon points="258,141 268,147 258,153" fill="#64748b"/><rect x="270" y="52" width="220" height="190" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/><text x="380" y="78" text-anchor="middle" font-size="14" font-weight="bold" fill="#15803d">2. Dinlerken</text><text x="380" y="108" text-anchor="middle" font-size="12" fill="#14532d">Kim? → sadîkî, tâlibetün</text><text x="380" y="132" text-anchor="middle" font-size="12" fill="#14532d">Ne? → hakîbetün, defterun</text><text x="380" y="156" text-anchor="middle" font-size="12" fill="#14532d">Nerede? → fi\'s-saffi</text><text x="380" y="180" text-anchor="middle" font-size="12" fill="#14532d">Anahtar kelimeleri not al</text><text x="380" y="212" text-anchor="middle" font-size="11" font-style="italic" fill="#166534">Hâzâ sadîkî Ahmedu, huve tâlibün.</text><line x1="494" y1="147" x2="508" y2="147" stroke="#64748b" stroke-width="2"/><polygon points="508,141 518,147 508,153" fill="#64748b"/><rect x="520" y="52" width="220" height="190" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/><text x="630" y="78" text-anchor="middle" font-size="14" font-weight="bold" fill="#b45309">3. Dinledikten Sonra</text><text x="630" y="108" text-anchor="middle" font-size="12" fill="#78350f">Bilgileri tabloya yerleştir</text><text x="630" y="132" text-anchor="middle" font-size="12" fill="#78350f">Doğru / yanlış kontrolü yap</text><text x="630" y="156" text-anchor="middle" font-size="12" fill="#78350f">Metni kendi sözlerinle anlat</text><text x="630" y="180" text-anchor="middle" font-size="12" fill="#78350f">Duygunu paylaş: Saffî cemîlün!</text><text x="630" y="212" text-anchor="middle" font-size="11" font-style="italic" fill="#92400e">Fi\'s-saffi sebbûratün ve tâviletün.</text><rect x="20" y="254" width="720" height="34" rx="8" fill="#e2e8f0"/><text x="380" y="276" text-anchor="middle" font-size="12" fill="#334155">Anahtar ipucu: «fî» duyduğunda arkasından bir yer adı gelir: fi\'s-saffi (sınıfta), fi\'l-hakîbeti (çantada)</text></svg>', 'b2': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect width="760" height="300" rx="14" fill="#f8fafc"/><text x="380" y="30" text-anchor="middle" font-size="16" font-weight="bold" fill="#1e293b">FÎ İLE KONUM CÜMLELERİ: ÇANTADA NELER VAR?</text><path d="M115 98 Q170 52 225 98" fill="none" stroke="#7c3aed" stroke-width="6"/><rect x="60" y="96" width="220" height="170" rx="16" fill="#ede9fe" stroke="#7c3aed" stroke-width="2"/><text x="170" y="118" text-anchor="middle" font-size="13" font-weight="bold" fill="#5b21b6">hakîbetün (çanta)</text><rect x="78" y="132" width="88" height="44" rx="8" fill="#ffffff" stroke="#a78bfa"/><text x="122" y="150" text-anchor="middle" font-size="12" font-weight="bold" fill="#4c1d95">kitâbün</text><text x="122" y="167" text-anchor="middle" font-size="11" fill="#6d28d9">kitap</text><rect x="174" y="132" width="88" height="44" rx="8" fill="#ffffff" stroke="#a78bfa"/><text x="218" y="150" text-anchor="middle" font-size="12" font-weight="bold" fill="#4c1d95">defterun</text><text x="218" y="167" text-anchor="middle" font-size="11" fill="#6d28d9">defter</text><rect x="78" y="190" width="88" height="44" rx="8" fill="#ffffff" stroke="#a78bfa"/><text x="122" y="208" text-anchor="middle" font-size="12" font-weight="bold" fill="#4c1d95">kalemün</text><text x="122" y="225" text-anchor="middle" font-size="11" fill="#6d28d9">kalem</text><rect x="174" y="190" width="88" height="44" rx="8" fill="#ffffff" stroke="#a78bfa"/><text x="218" y="208" text-anchor="middle" font-size="12" font-weight="bold" fill="#4c1d95">mimhâtün</text><text x="218" y="225" text-anchor="middle" font-size="11" fill="#6d28d9">silgi</text><text x="170" y="254" text-anchor="middle" font-size="11" fill="#5b21b6">ve (vav) bağlacıyla sıralanır</text><rect x="310" y="56" width="430" height="98" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/><text x="525" y="80" text-anchor="middle" font-size="14" font-weight="bold" fill="#1d4ed8">Kalıp 1: Belirli isim + fî + yer</text><text x="525" y="108" text-anchor="middle" font-size="13" fill="#1e3a8a">El-kalemu fi\'l-hakîbeti.</text><text x="525" y="134" text-anchor="middle" font-size="12" fill="#1e40af">Kalem çantadadır. (Bilinen kalemin yeri söylenir)</text><rect x="310" y="166" width="430" height="98" rx="10" fill="#fdf2f8" stroke="#db2777" stroke-width="1.5"/><text x="525" y="190" text-anchor="middle" font-size="14" font-weight="bold" fill="#be185d">Kalıp 2: Fî + yer + belirsiz isim</text><text x="525" y="218" text-anchor="middle" font-size="13" fill="#831843">Fi\'l-hakîbeti kalemün.</text><text x="525" y="244" text-anchor="middle" font-size="12" fill="#9d174d">Çantada bir kalem vardır. (Yeni bilgi verilir)</text><text x="380" y="288" text-anchor="middle" font-size="12" fill="#334155">Fî kelimesinden sonraki isim esreli okunur: fi\'s-saffi (sınıfta), fi\'l-medreseti (okulda)</text></svg>', 'b3': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect width="760" height="300" rx="14" fill="#f8fafc"/><text x="380" y="32" text-anchor="middle" font-size="16" font-weight="bold" fill="#1e293b">TAHMİN OYUNU: SOR, ONAYLA YA DA DÜZELT</text><rect x="20" y="110" width="150" height="70" rx="10" fill="#e0f2fe" stroke="#0284c7" stroke-width="1.5"/><text x="95" y="138" text-anchor="middle" font-size="13" font-weight="bold" fill="#075985">Mâ hâzihî?</text><text x="95" y="160" text-anchor="middle" font-size="12" fill="#0c4a6e">(Bu nedir?)</text><line x1="172" y1="145" x2="188" y2="145" stroke="#64748b" stroke-width="2"/><polygon points="188,139 198,145 188,151" fill="#64748b"/><rect x="200" y="110" width="170" height="70" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/><text x="285" y="138" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">Hel hâzâ kalemün?</text><text x="285" y="160" text-anchor="middle" font-size="12" fill="#78350f">(Bu bir kalem mi?)</text><line x1="372" y1="145" x2="380" y2="145" stroke="#64748b" stroke-width="2"/><polygon points="470,85 550,145 470,205 390,145" fill="#ede9fe" stroke="#7c3aed" stroke-width="1.5"/><text x="470" y="141" text-anchor="middle" font-size="12" font-weight="bold" fill="#5b21b6">Tahmin</text><text x="470" y="158" text-anchor="middle" font-size="12" font-weight="bold" fill="#5b21b6">doğru mu?</text><line x1="530" y1="130" x2="582" y2="94" stroke="#16a34a" stroke-width="2"/><polygon points="578,88 590,90 584,100" fill="#16a34a"/><text x="548" y="102" font-size="11" font-weight="bold" fill="#15803d">evet</text><line x1="530" y1="160" x2="582" y2="200" stroke="#dc2626" stroke-width="2"/><polygon points="584,194 590,206 578,204" fill="#dc2626"/><text x="540" y="196" font-size="11" font-weight="bold" fill="#b91c1c">hayır</text><rect x="592" y="52" width="150" height="76" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="1.5"/><text x="667" y="76" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Onay</text><text x="667" y="98" text-anchor="middle" font-size="12" fill="#14532d">Na\'am, hâzâ kalemün.</text><text x="667" y="117" text-anchor="middle" font-size="11" fill="#166534">(Evet, bu bir kalemdir.)</text><rect x="592" y="168" width="150" height="86" rx="10" fill="#fee2e2" stroke="#dc2626" stroke-width="1.5"/><text x="667" y="192" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Düzeltme</text><text x="667" y="213" text-anchor="middle" font-size="12" fill="#7f1d1d">Lâ, hâzihî mimhâtün.</text><text x="667" y="231" text-anchor="middle" font-size="11" fill="#991b1b">(Hayır, bu bir silgidir.)</text><text x="667" y="247" text-anchor="middle" font-size="10" font-weight="bold" fill="#991b1b">İşaret ismi değişti!</text><rect x="20" y="264" width="720" height="28" rx="8" fill="#e2e8f0"/><text x="380" y="283" text-anchor="middle" font-size="12" fill="#334155">Düzeltirken yeni eşyaya bak: sonu tâ merbûta ise hâzihî, değilse hâzâ kullanılır.</text></svg>', 'b4': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect width="760" height="300" rx="14" fill="#f8fafc"/><text x="380" y="32" text-anchor="middle" font-size="16" font-weight="bold" fill="#1e293b">ÖĞRETMEN DİYOR Kİ: YÖNERGE OYUNUNUN AŞAMALARI</text><rect x="20" y="52" width="165" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/><circle cx="102" cy="76" r="14" fill="#2563eb"/><text x="102" y="81" text-anchor="middle" font-size="13" font-weight="bold" fill="#ffffff">1</text><text x="102" y="110" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Öğretmen söyler</text><text x="102" y="136" text-anchor="middle" font-size="12" fill="#1e3a8a">Yâ Ömeru,</text><text x="102" y="156" text-anchor="middle" font-size="12" fill="#1e3a8a">eğlikı\'l-hakîbete!</text><text x="102" y="182" text-anchor="middle" font-size="11" fill="#1e40af">(Ömer, çantayı kapat!)</text><rect x="205" y="52" width="165" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/><circle cx="287" cy="76" r="14" fill="#16a34a"/><text x="287" y="81" text-anchor="middle" font-size="13" font-weight="bold" fill="#ffffff">2</text><text x="287" y="110" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Öğrenci dinler</text><text x="287" y="136" text-anchor="middle" font-size="12" fill="#14532d">Fiil: eğlik (kapat)</text><text x="287" y="156" text-anchor="middle" font-size="12" fill="#14532d">Nesne: el-hakîbete</text><text x="287" y="182" text-anchor="middle" font-size="11" fill="#166534">(çantayı)</text><rect x="390" y="52" width="165" height="175" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/><circle cx="472" cy="76" r="14" fill="#d97706"/><text x="472" y="81" text-anchor="middle" font-size="13" font-weight="bold" fill="#ffffff">3</text><text x="472" y="110" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Hareketi yapar</text><text x="472" y="136" text-anchor="middle" font-size="12" fill="#78350f">Çanta kapatılır</text><text x="472" y="156" text-anchor="middle" font-size="12" fill="#78350f">Yanlış hareket =</text><text x="472" y="176" text-anchor="middle" font-size="12" fill="#78350f">bir tur bekleme</text><rect x="575" y="52" width="165" height="175" rx="10" fill="#fdf2f8" stroke="#db2777" stroke-width="1.5"/><circle cx="657" cy="76" r="14" fill="#db2777"/><text x="657" y="81" text-anchor="middle" font-size="13" font-weight="bold" fill="#ffffff">4</text><text x="657" y="110" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Nazik cevap</text><text x="657" y="136" text-anchor="middle" font-size="12" fill="#831843">Tefaddal / Tefaddalî</text><text x="657" y="156" text-anchor="middle" font-size="11" fill="#9d174d">(Buyur)</text><text x="657" y="180" text-anchor="middle" font-size="12" fill="#831843">Şukran</text><text x="657" y="198" text-anchor="middle" font-size="11" fill="#9d174d">(Teşekkürler)</text><rect x="20" y="240" width="720" height="48" rx="10" fill="#e2e8f0"/><text x="380" y="260" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e293b">Bağlantı kuralı: cezimli emir + el takılı nesne → esre ile bağlanır</text><text x="380" y="279" text-anchor="middle" font-size="12" fill="#334155">iftah + ed-deftera = iftahi\'d-deftera · huz + el-kaleme = huzi\'l-kaleme</text></svg>', 'b5': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect width="760" height="300" rx="14" fill="#f8fafc"/><text x="380" y="30" text-anchor="middle" font-size="16" font-weight="bold" fill="#1e293b">HARFLERİN KELİME İÇİNDEKİ HÂLLERİ VE BİTİŞMEYEN HARFLER</text><rect x="20" y="48" width="250" height="204" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="1.5"/><text x="145" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">Sonraki harfe bitişmeyen 6 harf</text><circle cx="75" cy="122" r="28" fill="#ffedd5" stroke="#fb923c"/><text x="75" y="127" text-anchor="middle" font-size="13" font-weight="bold" fill="#9a3412">Elif</text><circle cx="145" cy="122" r="28" fill="#ffedd5" stroke="#fb923c"/><text x="145" y="127" text-anchor="middle" font-size="13" font-weight="bold" fill="#9a3412">Dâl</text><circle cx="215" cy="122" r="28" fill="#ffedd5" stroke="#fb923c"/><text x="215" y="127" text-anchor="middle" font-size="13" font-weight="bold" fill="#9a3412">Zâl</text><circle cx="75" cy="192" r="28" fill="#ffedd5" stroke="#fb923c"/><text x="75" y="197" text-anchor="middle" font-size="13" font-weight="bold" fill="#9a3412">Râ</text><circle cx="145" cy="192" r="28" fill="#ffedd5" stroke="#fb923c"/><text x="145" y="197" text-anchor="middle" font-size="13" font-weight="bold" fill="#9a3412">Zây</text><circle cx="215" cy="192" r="28" fill="#ffedd5" stroke="#fb923c"/><text x="215" y="197" text-anchor="middle" font-size="13" font-weight="bold" fill="#9a3412">Vav</text><text x="145" y="240" text-anchor="middle" font-size="11" fill="#9a3412">Yalnız önceki harfe bağlanırlar</text><rect x="290" y="48" width="450" height="204" rx="10" fill="#f0f9ff" stroke="#0284c7" stroke-width="1.5"/><text x="515" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0369a1">Hedef kelimeleri parçalara ayırma</text><text x="310" y="104" font-size="13" fill="#0c4a6e">Defterun → [de] + [fterun] = 2 parça</text><text x="310" y="132" font-size="13" fill="#0c4a6e">Medresetün → [med] + [re] + [setün] = 3 parça</text><text x="310" y="160" font-size="13" fill="#0c4a6e">Tâviletün → [tâ] + [vi] + [letün] = 3 parça</text><text x="310" y="188" font-size="13" fill="#0c4a6e">Kürsiyyün → [kür] + [siyyün] = 2 parça</text><text x="310" y="216" font-size="13" fill="#0c4a6e">Hakîbetün → [hakîbetün] = 1 parça (hepsi bitişik)</text><text x="310" y="240" font-size="11" fill="#075985">Tâ merbûta: tâlibetün (bitişik) · sebbûratün (ayrı)</text><rect x="20" y="262" width="720" height="30" rx="8" fill="#e2e8f0"/><text x="380" y="282" text-anchor="middle" font-size="12" fill="#334155">Harekeler: üstün (a/e) · esre (i/ı) · ötre (u/ü) · cezim (harekesiz) · şedde (çift okuma)</text></svg>', 'b6': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect width="760" height="300" rx="14" fill="#f8fafc"/><text x="380" y="30" text-anchor="middle" font-size="16" font-weight="bold" fill="#1e293b">SINIFIMI TANITIYORUM: KONUŞMA BASAMAKLARI VE ÖZ DEĞERLENDİRME</text><rect x="20" y="212" width="110" height="70" rx="8" fill="#dbeafe" stroke="#2563eb"/><text x="75" y="234" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">1. Hazırlan</text><text x="75" y="254" text-anchor="middle" font-size="11" fill="#1e3a8a">Kelime listesi</text><text x="75" y="270" text-anchor="middle" font-size="11" fill="#1e3a8a">eril / dişil</text><rect x="135" y="168" width="110" height="114" rx="8" fill="#dcfce7" stroke="#16a34a"/><text x="190" y="190" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">2. Dinle ve</text><text x="190" y="206" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">taklit et</text><text x="190" y="230" text-anchor="middle" font-size="11" fill="#14532d">Model metni</text><text x="190" y="246" text-anchor="middle" font-size="11" fill="#14532d">tekrar et</text><rect x="250" y="124" width="110" height="158" rx="8" fill="#fef3c7" stroke="#d97706"/><text x="305" y="146" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">3. Cümle kur</text><text x="305" y="170" text-anchor="middle" font-size="11" fill="#78350f">Hâzihî hakîbetî,</text><text x="305" y="186" text-anchor="middle" font-size="11" fill="#78350f">fi\'l-hakîbeti</text><text x="305" y="202" text-anchor="middle" font-size="11" fill="#78350f">kitâbün.</text><rect x="365" y="80" width="110" height="202" rx="8" fill="#fce7f3" stroke="#db2777"/><text x="420" y="102" text-anchor="middle" font-size="12" font-weight="bold" fill="#be185d">4. Sun ve</text><text x="420" y="118" text-anchor="middle" font-size="12" font-weight="bold" fill="#be185d">paylaş</text><text x="420" y="144" text-anchor="middle" font-size="11" fill="#831843">Sınıfa anlat</text><text x="420" y="160" text-anchor="middle" font-size="11" fill="#831843">Duygunu söyle</text><text x="420" y="186" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">El-ilmü nâfi\'un!</text><rect x="495" y="52" width="245" height="230" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/><text x="617" y="76" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Öz Değerlendirme</text><rect x="512" y="92" width="14" height="14" rx="3" fill="#ffffff" stroke="#16a34a"/><text x="534" y="104" font-size="12" fill="#14532d">Eşyaları adlandırıyorum</text><rect x="512" y="122" width="14" height="14" rx="3" fill="#ffffff" stroke="#16a34a"/><text x="534" y="134" font-size="12" fill="#14532d">Hel sorusu soruyorum</text><rect x="512" y="152" width="14" height="14" rx="3" fill="#ffffff" stroke="#16a34a"/><text x="534" y="164" font-size="12" fill="#14532d">Fî ile yer söylüyorum</text><rect x="512" y="182" width="14" height="14" rx="3" fill="#ffffff" stroke="#16a34a"/><text x="534" y="194" font-size="12" fill="#14532d">Yönergeleri uyguluyorum</text><rect x="512" y="212" width="14" height="14" rx="3" fill="#ffffff" stroke="#16a34a"/><text x="534" y="224" font-size="12" fill="#14532d">Harfleri doğru bitiştiriyorum</text><rect x="512" y="242" width="14" height="14" rx="3" fill="#ffffff" stroke="#16a34a"/><text x="534" y="254" font-size="12" fill="#14532d">Sınıfımı Arapça tanıtıyorum</text></svg>'}

def uygula(v):
    for idx, b in enumerate(v.get('bolumler', []), 1):
        svg = GORSELLER.get(f'b{idx}') or GORSELLER.get(str(idx))
        if svg:
            b['gorsel'] = svg
    return v
